import re


def clean_text(text):
    if not text:
        return ""
    text = re.sub(r'<[^>]+>', '', text)
    text = text.replace('\xa0', ' ')
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

print(clean_text('<p>  \u5ba2\u670d\u7535\u8bdd\u4e3a 400-123-4567\xa0 </p>'))

